import pg from 'pg';
import {PostgresAgentMemory} from '../../dist/index.js';
const pool=new pg.Pool({connectionString:process.env.APP_MIXER_TEST_POSTGRES_URL,options:`-c search_path=${process.env.APP_MIXER_TEST_SCHEMA}`}),phase=process.env.APP_MIXER_TEST_PHASE;
const hold=()=>new Promise(()=>{});
const store=new PostgresAgentMemory({enabled:true,audit:true,maxEntries:10,maxTtlMs:10000,clock:()=>100,authorize:()=>true,query:(sql,args)=>pool.query(sql,args),transaction:async operation=>{const client=await pool.connect();try{await client.query('BEGIN');const result=await operation((sql,args)=>client.query(sql,args));if(phase==='before-commit'){process.send('before-commit');await hold();}await client.query('COMMIT');if(phase==='after-commit'){process.send('after-commit');await hold();}return result;}catch(error){await client.query('ROLLBACK');throw error;}finally{client.release();}}});
try{await store.put({tenantId:'tenant',principalId:'worker'},{tenantId:'tenant',agentId:'agent',owner:{kind:'organization',id:'org'},kind:'semantic'},phase,{phase},{expectedRevision:null,expiresAt:500,provenance:{kind:'run',id:'run'}});throw Error('Expected termination');}catch(error){process.send({error:String(error)});process.exitCode=1;await pool.end();}
